using Microsoft.AspNetCore.Identity;
namespace VanEscolar.Api.Domain;
public sealed class AppUser : IdentityUser<Guid> { }
public sealed class Tenant { public Guid Id { get; set; } = Guid.NewGuid(); public string DisplayName { get; set; } = ""; public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class Membership { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid UserId { get; set; } public string Role { get; set; } = "TenantOwner"; public bool Active { get; set; } = true; }
public sealed class School { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public string Name { get; set; } = ""; public string Address { get; set; } = ""; public bool Active { get; set; } = true; }
public sealed class Student { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid SchoolId { get; set; } public string FullName { get; set; } = ""; public string Shift { get; set; } = "Manhã"; public string PickupAddress { get; set; } = ""; public string DropoffAddress { get; set; } = ""; public bool Active { get; set; } = true; }
public sealed class Guardian { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public string FullName { get; set; } = ""; public string Phone { get; set; } = ""; public string Email { get; set; } = ""; }
public sealed class StudentGuardian { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid StudentId { get; set; } public Guid GuardianId { get; set; } public string Relationship { get; set; } = "Responsável"; }
public sealed class TransportContract { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid StudentId { get; set; } public decimal MonthlyAmount { get; set; } public int DueDay { get; set; } public DateOnly StartsOn { get; set; } public int Installments { get; set; } = 12; public string Status { get; set; } = "Active"; }
public sealed class Charge { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid ContractId { get; set; } public Guid StudentId { get; set; } public DateOnly Competence { get; set; } public DateOnly DueDate { get; set; } public decimal Amount { get; set; } public string Status { get; set; } = "Open"; }
public sealed class Payment { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid ChargeId { get; set; } public decimal Amount { get; set; } public DateTime PaidAtUtc { get; set; } = DateTime.UtcNow; public string Method { get; set; } = "PIX"; public string IdempotencyKey { get; set; } = ""; public Guid CreatedByUserId { get; set; } public bool Reversed { get; set; } }
public sealed class Expense { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public string Category { get; set; } = ""; public string Description { get; set; } = ""; public decimal Amount { get; set; } public DateOnly Date { get; set; } public string Status { get; set; } = "Active"; }
public sealed class AbsenceNotice { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid StudentId { get; set; } public DateOnly Date { get; set; } public string Period { get; set; } = "Dia inteiro"; public string Reason { get; set; } = ""; public Guid CreatedByUserId { get; set; } public DateTime? AcknowledgedAtUtc { get; set; } }
public sealed class AuditEvent { public Guid Id { get; set; } = Guid.NewGuid(); public Guid TenantId { get; set; } public Guid UserId { get; set; } public string Action { get; set; } = ""; public string EntityType { get; set; } = ""; public Guid EntityId { get; set; } public DateTime OccurredAtUtc { get; set; } = DateTime.UtcNow; }
